import React from 'react';
import { useCart } from '../../context/CartContext';
import { Link } from 'react-router-dom';
import './Checkout.css';

// Re-using the featured accessories data from Home.js for recommendations
const recommendedAccessories = [
  {
    id: 'a1',
    name: 'Modern Ceramic Pot',
    price: 499,
    image: 'https://images.unsplash.com/photo-1557291269-96f37fd69392?q=80&w=1974&auto=format&fit=crop',
  },
  {
    id: 'a2',
    name: 'Stylish Watering Can',
    price: 799,
    image: 'https://images.unsplash.com/photo-1586251986492-8a1c2a5a5b18?q=80&w=1974&auto=format&fit=crop',
  },
  {
    id: 'a3',
    name: 'Gardening Tool Set',
    price: 1499,
    image: 'https://images.unsplash.com/photo-1617582995183-55499ae3f3bf?q=80&w=1974&auto=format&fit=crop',
  },
];

const Checkout = () => {
  const { cartItems, addItem, clearCart } = useCart(); // Assuming clearCart will be added

  const calculateTotal = () => {
    return cartItems.reduce((total, item) => total + item.price * item.quantity, 0).toFixed(2);
  };

  const handlePlaceOrder = (e) => {
    e.preventDefault();
    // In the next steps, this will be moved to use the OrderContext
    alert('Order placed successfully! (This is a simulation)');
    // clearCart(); // This will be enabled later
    // navigate('/my-orders');
  };

  // Simple logic: show recommendations if there are plants in the cart
  const showRecommendations = cartItems.some(item => item.id.startsWith('p'));

  return (
    <div className="checkout-page">
      <div className="checkout-container">
        <div className="checkout-form-container">
          <h2>Shipping Information</h2>
          <form id="checkout-form" onSubmit={handlePlaceOrder}>
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="name">Full Name</label>
                <input type="text" id="name" required />
              </div>
            </div>
            <div className="form-group">
              <label htmlFor="address">Street Address</label>
              <input type="text" id="address" required />
            </div>
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="city">City</label>
                <input type="text" id="city" required />
              </div>
              <div className="form-group">
                <label htmlFor="zip">Postal Code</label>
                <input type="text" id="zip" required />
              </div>
            </div>

            <h2 className="payment-title">Payment Method</h2>
            <div className="payment-methods">
              <label className="payment-option">
                <input type="radio" name="payment" value="credit" defaultChecked />
                <span>Credit Card</span>
              </label>
              <label className="payment-option">
                <input type="radio" name="payment" value="paypal" />
                <span>PayPal</span>
              </label>
            </div>
          </form>
        </div>

        <div className="order-summary-container">
          <h2>Order Summary</h2>
          <div className="summary-items">
            {cartItems.length > 0 ? cartItems.map(item => (
              <div key={item.id} className="summary-item">
                <span>{item.name} (x{item.quantity})</span>
                <span>₹{(item.price * item.quantity).toFixed(2)}</span>
              </div>
            )) : <p>Your cart is empty.</p>}
          </div>
          <div className="summary-total">
            <strong>Total</strong>
            <strong>₹{calculateTotal()}</strong>
          </div>
          <button type="submit" form="checkout-form" className="place-order-btn">Place Order</button>
        </div>
      </div>

      {showRecommendations && (
        <div className="recommendations-container">
          <h2>Recommended For You</h2>
          <div className="recommendations-grid">
            {recommendedAccessories.map(acc => (
              <div key={acc.id} className="rec-card">
                <img src={acc.image} alt={acc.name} />
                <h3>{acc.name}</h3>
                <p className="price">₹{acc.price}</p>
                <button onClick={() => addItem(acc)}>Add to Cart</button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default Checkout;
